def pt(v):return [round(pcbnew.ToMM(v.x),6),round(pcbnew.ToMM(v.y),6)]
def vec(v):return pcbnew.VECTOR2I(pcbnew.FromMM(v[0]),pcbnew.FromMM(v[1]))
def apply(board):
 fps={f.GetReference():f for f in board.GetFootprints()}
 for ref,pin,net,xy in [('U7','3','/I2C_SCL',[110.5,111.6]),('U7','4','/I2C_SDA',[110.,111.6]),('U12','1','/I2C_SDA',[104.2,135.9]),('U12','2','/I2C_SCL',[104.2,135.1]),('U10','6','/I2C_SDA',[110.65,137.5])]:
  q=[p for p in fps[ref].Pads() if p.GetNumber()==pin]
  if len(q)!=1 or q[0].GetNetname()!=net or pt(q[0].GetPosition())!=xy:raise ValueError('source pad mismatch '+ref+'.'+pin)
 tracks=list(board.GetTracks());items={t.m_Uuid.AsString():t for t in tracks}
 via=items['dfd0eecd-1774-4a3a-a6ab-b0423e94d1f3'];row=items['2e47067e-d998-4490-a5cf-caa01d3487fc']
 if via.GetNetname()!='/CELL_WE' or pt(via.GetPosition())!=[103.8,116.65] or row.GetNetname()!='/CELL_WE' or pt(row.GetEnd())!=[103.8,116.65]:raise ValueError('WE escape source changed')
 grounds=[([111.5,111.6],[111.5,112.1]),([111.5,112.1],[111.2,112.4])]
 for a,b in grounds:
  if not any(t.GetNetname()=='GND' and t.GetLayer()==pcbnew.F_Cu and {tuple(pt(t.GetStart())),tuple(pt(t.GetEnd()))}=={tuple(a),tuple(b)} for t in tracks):raise ValueError('missing required U7 ground tie')
 remove=[t for t in tracks if t.GetNetname() in ['/I2C_SCL','/I2C_SDA']]
 for t in remove:board.RemoveNative(t)
 via.SetPosition(vec([103.8,116.45]));row.SetEnd(vec([104.2,116.65]))
 added=[]
 for s in ROUTES:
  if s['kind']=='PCB_VIA':
   t=pcbnew.PCB_VIA(board);t.SetPosition(vec(s['start']));t.SetViaType(pcbnew.VIATYPE_THROUGH);t.SetLayerPair(pcbnew.F_Cu,pcbnew.B_Cu);t.SetDrill(pcbnew.FromMM(.2))
  else:
   t=pcbnew.PCB_TRACK(board);t.SetLayer(board.GetLayerID(s['layer']));t.SetStart(vec(s['start']));t.SetEnd(vec(s['end']))
  t.SetNet(board.FindNet(s['net']));t.SetWidth(pcbnew.FromMM(s['width']));t.SetLocked(True);board.Add(t);added.append(t)
 for layer,a,b in [(pcbnew.B_Cu,[103.8,116.45],[103.8,116.65]),(pcbnew.F_Cu,[103.8,116.45],[104.2,116.65])]:
  t=pcbnew.PCB_TRACK(board);t.SetLayer(layer);t.SetStart(vec(a));t.SetEnd(vec(b));t.SetWidth(pcbnew.FromMM(.2));t.SetNet(board.FindNet('/CELL_WE'));t.SetLocked(True);board.Add(t);added.append(t)
 return {'bus_removed':len(remove),'bus_added':len(ROUTES),'bus_vias':sum(s['kind']=='PCB_VIA' for s in ROUTES),'WE_changes':2,'WE_tracks_added':2}
